mapper.select:
SELECT MAX(so.create_time)
FROM wms_sales_out so
WHERE so.del_flag = '0'
  AND so.tenant_id = #{tenantId}

      AND so.warehouse_id = #{warehouseId}

SELECT * FROM ( SELECT c.customer_code AS customerCode, c.customer_name AS customerName, c.contact, c.phone, COALESCE(order_counts.cnt, 0) AS orderCount, COALESCE(order_amounts.amt, 0) AS orderAmount, COALESCE(out_amounts.amt, 0) AS outAmount, COALESCE(return_amounts.amt, 0) AS returnAmount, COALESCE(out_amounts.amt, 0) - COALESCE(return_amounts.amt, 0) AS netSales, COALESCE(out_amounts.amt, 0) - COALESCE(received_totals.amt, 0) AS arAmount, COALESCE(received_totals.amt, 0) AS receivedAmount, CASE WHEN COALESCE(out_amounts.amt, 0) > 0 THEN ROUND((COALESCE(received_totals.amt, 0) / out_amounts.amt) * 100, 2) ELSE 0 END AS receiptRate, MAX(so.create_time) AS lastOrderDate FROM wms_customer c
INNER JOIN (SELECT id FROM wms_customer WHERE id IN
#{id}
) filtered_customers ON c.id = filtered_customers.id
LEFT JOIN ( SELECT customer_id, COUNT(*) AS cnt, SUM(total_amount) AS amt FROM wms_sales_order WHERE del_flag = 0
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(create_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY customer_id ) order_counts ON c.id = order_counts.customer_id LEFT JOIN ( SELECT customer_id, SUM(total_amount) AS amt FROM wms_sales_order WHERE del_flag = 0
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(create_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY customer_id ) order_amounts ON c.id = order_amounts.customer_id LEFT JOIN ( SELECT customer_id, SUM(total_amount) AS amt FROM wms_sales_out WHERE del_flag = 0
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(create_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY customer_id ) out_amounts ON c.id = out_amounts.customer_id LEFT JOIN ( SELECT customer_id, SUM(total_amount) AS amt FROM wms_sales_return WHERE del_flag = 0
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(create_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY customer_id ) return_amounts ON c.id = return_amounts.customer_id LEFT JOIN ( SELECT sout.customer_id, SUM(sout.received_amount) AS amt FROM wms_sales_out sout WHERE sout.del_flag = 0
AND DATE(sout.create_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(sout.create_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY sout.customer_id ) received_totals ON c.id = received_totals.customer_id LEFT JOIN wms_sales_order so ON c.id = so.customer_id AND so.del_flag = 0 WHERE c.del_flag = 0 GROUP BY c.id, c.customer_code, c.customer_name, c.contact, c.phone, order_counts.cnt, order_amounts.amt, out_amounts.amt, return_amounts.amt, received_totals.amt ) t WHERE orderAmount > 0 OR outAmount > 0 ORDER BY netSales DESC
